drop table if exists `system_dept`;
drop table if exists `system_user_dept`;

CREATE TABLE `system_dept` (
   `id` bigint(20) NOT NULL COMMENT '部门id',
   `name` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '部门名称',
   `ancestors` varchar(255) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '祖级列表',
   `parent_id` bigint(20) NOT NULL DEFAULT '0' COMMENT '父部门id',
   `sort` int(11) NOT NULL DEFAULT '0' COMMENT '显示顺序',
   `status` bit(1) NOT NULL DEFAULT b'0' COMMENT '部门状态（0正常 1停用）',
   `level` tinyint(1) DEFAULT NULL COMMENT '等级-最多五级',
   `update_flag` bit(1) DEFAULT NULL COMMENT '能否修改 0能 1不能',
   `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
   `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
   `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
   `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
   `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
   `business_id` bigint(20) NOT NULL DEFAULT '0' COMMENT '业务线ID',
   PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='部门表';


CREATE TABLE `system_user_dept` (
    `user_dept_id` bigint(20) NOT NULL COMMENT 'id',
    `user_id` bigint(20) NOT NULL COMMENT '用户id',
    `dept_id` bigint(20) NOT NULL COMMENT '部门id',
    `type` bit(1) NOT NULL DEFAULT b'1' COMMENT '0负责人 1普通',
    `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
    `business_id` bigint(20) NOT NULL DEFAULT '0' COMMENT '业务线ID',
    PRIMARY KEY (`user_dept_id`),
    KEY `idx_deptid` (`dept_id`) USING BTREE COMMENT '部门id索引'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='用户部门关系表';

